// ── Google Analytics Helpers ──────────────────────────────
const { BetaAnalyticsDataClient } = require("@google-analytics/data");
const GA_SERVICE_ACCOUNT_KEY = defineSecret("GA_SERVICE_ACCOUNT_KEY");
const GA_PROPERTY_ID = "533664712";

async function getAnalyticsData(propertyId, startDate, endDate) {
  const client = new BetaAnalyticsDataClient({
    credentials: JSON.parse(GA_SERVICE_ACCOUNT_KEY.value()),
  });

  // Overall metrics
  const [metricsResponse] = await client.runReport({
    property: `properties/${propertyId}`,
    dateRanges: [{ startDate, endDate }],
    metrics: [
      { name: "sessions" },
      { name: "activeUsers" },
      { name: "screenPageViews" },
    ],
  });

  const sessions   = parseInt(metricsResponse.rows?.[0]?.metricValues?.[0]?.value || "0");
  const visitors   = parseInt(metricsResponse.rows?.[0]?.metricValues?.[1]?.value || "0");
  const pageViews  = parseInt(metricsResponse.rows?.[0]?.metricValues?.[2]?.value || "0");

  // Top pages
  const [pagesResponse] = await client.runReport({
    property: `properties/${propertyId}`,
    dateRanges: [{ startDate, endDate }],
    dimensions: [{ name: "pagePath" }],
    metrics: [{ name: "screenPageViews" }],
    orderBys: [{ metric: { metricName: "screenPageViews" }, desc: true }],
    limit: 5,
  });

  const topPages = (pagesResponse.rows || []).map(row => ({
    path:  row.dimensionValues?.[0]?.value || "/",
    views: parseInt(row.metricValues?.[0]?.value || "0"),
  }));

  return { sessions, visitors, pageViews, topPages };
}

function buildReportEmail(data, dateLabel, districtName) {
  const topPagesRows = data.topPages.length
    ? data.topPages.map((p, i) => {
        const barWidth = data.topPages[0].views > 0
          ? Math.round((p.views / data.topPages[0].views) * 100)
          : 0;
        const pageName = p.path === "/" ? "Home" :
          p.path.replace(/\.html$/, "").replace(/^\//, "")
               .replace(/-/g," ").replace(/\b\w/g, c => c.toUpperCase());
        return `<tr>
          <td style="padding:10px 12px;border-bottom:1px solid #f0ebe3">
            <div style="font-size:13px;color:#222;font-weight:500;margin-bottom:4px">${pageName}</div>
            <div style="font-size:11px;color:#999">${p.path}</div>
            <div style="margin-top:5px;height:4px;background:#f0ebe3;border-radius:2px">
              <div style="height:4px;width:${barWidth}%;background:#b83535;border-radius:2px"></div>
            </div>
          </td>
          <td style="padding:10px 12px;border-bottom:1px solid #f0ebe3;text-align:right;font-size:14px;font-weight:bold;color:#1e3a5c;white-space:nowrap">${p.views}</td>
        </tr>`;
      }).join("")
    : '<tr><td colspan="2" style="padding:16px;text-align:center;color:#aaa;font-size:13px">No page data yet — check back tomorrow</td></tr>';

  const now = new Date().toLocaleTimeString("en-US", { hour:"numeric", minute:"2-digit", timeZone:"America/Chicago" });

  return `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f4efe6;font-family:Georgia,serif">
<div style="max-width:600px;margin:0 auto;padding:24px 16px">

  <!-- Header -->
  <div style="background:#1e3a5c;border-radius:12px 12px 0 0;padding:32px 32px 28px;color:white">
    <div style="font-family:Arial,sans-serif;font-size:11px;letter-spacing:.12em;text-transform:uppercase;opacity:.6;margin-bottom:8px">Daily Traffic Report</div>
    <h1 style="margin:0 0 6px;font-size:26px;font-weight:700;letter-spacing:-.3px">${districtName}</h1>
    <div style="font-family:Arial,sans-serif;font-size:14px;opacity:.75">${dateLabel}</div>
  </div>

  <!-- Stats Row -->
  <div style="background:white;padding:28px 32px;display:block">
    <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
      <tr>
        <td width="33%" style="text-align:center;padding:16px 8px">
          <div style="background:#f4efe6;border-radius:10px;padding:20px 12px">
            <div style="font-size:36px;font-weight:700;color:#1e3a5c;line-height:1">${data.sessions}</div>
            <div style="font-family:Arial,sans-serif;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#888;margin-top:6px">Sessions</div>
          </div>
        </td>
        <td width="33%" style="text-align:center;padding:16px 8px">
          <div style="background:#f4efe6;border-radius:10px;padding:20px 12px">
            <div style="font-size:36px;font-weight:700;color:#1e3a5c;line-height:1">${data.visitors}</div>
            <div style="font-family:Arial,sans-serif;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#888;margin-top:6px">Visitors</div>
          </div>
        </td>
        <td width="33%" style="text-align:center;padding:16px 8px">
          <div style="background:#f4efe6;border-radius:10px;padding:20px 12px">
            <div style="font-size:36px;font-weight:700;color:#b83535;line-height:1">${data.pageViews}</div>
            <div style="font-family:Arial,sans-serif;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#888;margin-top:6px">Page Views</div>
          </div>
        </td>
      </tr>
    </table>
  </div>

  <!-- Divider -->
  <div style="background:white;padding:0 32px"><div style="border-top:1px solid #f0ebe3"></div></div>

  <!-- Top Pages -->
  <div style="background:white;padding:24px 32px 8px">
    <div style="font-family:Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#b83535;margin-bottom:16px">Top Pages</div>
    <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
      <tr style="background:#f4efe6">
        <th style="padding:8px 12px;text-align:left;font-family:Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#666">Page</th>
        <th style="padding:8px 12px;text-align:right;font-family:Arial,sans-serif;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#666">Views</th>
      </tr>
      ${topPagesRows}
    </table>
  </div>

  <!-- Footer -->
  <div style="background:#1e3a5c;border-radius:0 0 12px 12px;padding:20px 32px;display:flex">
    <table width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td style="font-family:Arial,sans-serif;font-size:12px;color:rgba(255,255,255,.5)">
          ${districtName} &mdash; <a href="https://artdepotdistrict.com" style="color:rgba(255,255,255,.6);text-decoration:none">artdepotdistrict.com</a>
        </td>
        <td style="font-family:Arial,sans-serif;font-size:12px;color:rgba(255,255,255,.4);text-align:right">
          Sent ${now} CT
        </td>
      </tr>
    </table>
  </div>

</div>
</body>
</html>`;
}

// ── Daily Analytics Report — 8am CT ───────────────────────
exports.dailyAnalyticsReport = onSchedule(
  {
    schedule:  "0 8 * * *",
    timeZone:  "America/Chicago",
    secrets:   [RESEND_API_KEY, GA_SERVICE_ACCOUNT_KEY],
  },
  async () => {
    const db = getFirestore();

    // Load config
    let propertyId  = GA_PROPERTY_ID;
    let emails      = [];
    let districtName = "Art Depot District";
    try {
      const snap = await db.doc("analytics_config/main").get();
      if (snap.exists) {
        const cfg = snap.data();
        if (cfg.propertyId)   propertyId   = cfg.propertyId;
        if (cfg.reportEmails) emails        = cfg.reportEmails;
      }
      const cfgSnap = await db.doc("site_config/main").get();
      if (cfgSnap.exists && cfgSnap.data().districtName) {
        districtName = cfgSnap.data().districtName;
      }
    } catch(e) { console.error("Config load failed:", e); }

    if (!emails.length) { console.log("No analytics report emails configured"); return; }

    const yesterday  = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const dateStr    = yesterday.toISOString().split("T")[0];
    const dateLabel  = yesterday.toLocaleDateString("en-US", { weekday:"long", year:"numeric", month:"long", day:"numeric" });

    let data;
    try {
      data = await getAnalyticsData(propertyId, dateStr, dateStr);
    } catch(e) {
      console.error("GA data fetch failed:", e);
      return;
    }

    const html    = buildReportEmail(data, dateLabel, districtName);
    const resend  = new Resend(RESEND_API_KEY.value());

    try {
      await resend.emails.send({
        from:    `${districtName} <noreply@797distillery.com>`,
        to:      emails,
        subject: `Daily Traffic Report — ${dateLabel}`,
        html,
      });
      console.log(`Analytics report sent to ${emails.length} recipient(s)`);
    } catch(e) {
      console.error("Analytics email failed:", e);
      return;
    }

    // Save to report history
    try {
      await db.collection("analytics_reports").add({
        date:      dateStr,
        dateLabel,
        sessions:  data.sessions,
        visitors:  data.visitors,
        pageViews: data.pageViews,
        topPages:  data.topPages,
        sentTo:    emails,
        sentAt:    FieldValue.serverTimestamp(),
      });
    } catch(e) { console.error("Failed to save report history:", e); }
  }
);

// ── Send Analytics Report Now (admin button) ───────────────
exports.sendAnalyticsNow = onRequest(
  { secrets: [RESEND_API_KEY, GA_SERVICE_ACCOUNT_KEY], cors: true },
  async (req, res) => {
    if (req.method !== "POST") return res.status(405).json({ error: "Method not allowed" });

    const db = getFirestore();
    let propertyId   = GA_PROPERTY_ID;
    let emails       = [];
    let districtName = "Art Depot District";

    try {
      const snap = await db.doc("analytics_config/main").get();
      if (snap.exists) {
        const cfg = snap.data();
        if (cfg.propertyId)   propertyId = cfg.propertyId;
        if (cfg.reportEmails) emails     = cfg.reportEmails;
      }
      const cfgSnap = await db.doc("site_config/main").get();
      if (cfgSnap.exists && cfgSnap.data().districtName) {
        districtName = cfgSnap.data().districtName;
      }
    } catch(e) { return res.status(500).json({ error: "Config load failed" }); }

    if (!emails.length) return res.status(400).json({ error: "No report emails configured" });

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const dateStr   = yesterday.toISOString().split("T")[0];
    const dateLabel = yesterday.toLocaleDateString("en-US", { weekday:"long", year:"numeric", month:"long", day:"numeric" });

    let data;
    try {
      data = await getAnalyticsData(propertyId, dateStr, dateStr);
    } catch(e) {
      console.error("GA data fetch failed:", e);
      return res.status(500).json({ error: "Failed to fetch analytics data. Check GA permissions." });
    }

    const html   = buildReportEmail(data, dateLabel, districtName);
    const resend = new Resend(RESEND_API_KEY.value());

    try {
      await resend.emails.send({
        from:    `${districtName} <noreply@797distillery.com>`,
        to:      emails,
        subject: `Traffic Report — ${dateLabel}`,
        html,
      });
    } catch(e) {
      return res.status(500).json({ error: "Email send failed" });
    }

    try {
      await db.collection("analytics_reports").add({
        date:      dateStr,
        dateLabel,
        sessions:  data.sessions,
        visitors:  data.visitors,
        pageViews: data.pageViews,
        topPages:  data.topPages,
        sentTo:    emails,
        sentAt:    FieldValue.serverTimestamp(),
      });
    } catch(e) { /* silent */ }

    return res.json({ success: true, sessions: data.sessions, visitors: data.visitors, pageViews: data.pageViews });
  }
);

// ── Get Analytics Stats (admin dashboard) ─────────────────
exports.getAnalyticsStats = onRequest(
  { secrets: [GA_SERVICE_ACCOUNT_KEY], cors: true },
  async (req, res) => {
    if (req.method !== "GET") return res.status(405).json({ error: "Method not allowed" });

    const db = getFirestore();
    let propertyId = GA_PROPERTY_ID;
    try {
      const snap = await db.doc("analytics_config/main").get();
      if (snap.exists && snap.data().propertyId) propertyId = snap.data().propertyId;
    } catch(e) { /* use default */ }

    // Yesterday
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const dateStr = yesterday.toISOString().split("T")[0];

    // Last 30 days
    const thirtyAgo = new Date();
    thirtyAgo.setDate(thirtyAgo.getDate() - 30);
    const thirtyStr = thirtyAgo.toISOString().split("T")[0];

    try {
      const [yesterday30] = await Promise.all([
        getAnalyticsData(propertyId, thirtyStr, dateStr),
      ]);
      const yesterdayOnly = await getAnalyticsData(propertyId, dateStr, dateStr);
      return res.json({
        yesterday: yesterdayOnly,
        thirtyDays: yesterday30,
        dateStr,
      });
    } catch(e) {
      console.error("getAnalyticsStats error:", e);
      return res.status(500).json({ error: e.message });
    }
  }
);

// ── Chat Proxy (existing — unchanged) ─────────────────────
exports.chat = onRequest(
  { secrets: [ANTHROPIC_API_KEY], cors: true },
  async (req, res) => {
    if (req.method !== "POST") return res.status(405).json({ error: "Method not allowed" });
    const { messages = [] } = req.body;
    if (!messages.length) return res.status(400).json({ error: "No messages" });
    const db = getFirestore();
    let businesses = [], faqs = [];
    try {
      const bizSnap = await db.collection("businesses").where("published","==",true).get();
      businesses    = bizSnap.docs.map(d => {
        const b = d.data();
        return `${b.name} (${b.category||"business"}): ${b.summary||""} — ${b.address||""} — Hours: ${b.hours||"see website"} — Phone: ${b.phone||"N/A"} — Website: ${b.website||"N/A"}`;
      });
      const faqSnap = await db.collection("faqs").where("published","==",true).get();
      faqs          = faqSnap.docs.map(d => { const f=d.data(); return `Q: ${f.question}\nA: ${f.answer}`; });
    } catch(e) { console.error("Error loading district data:", e); }
    let depotInfo = "";
    try {
      const year   = new Date().getFullYear().toString();
      const ddSnap = await db.doc(`depot_days/${year}`).get();
      if (ddSnap.exists) {
        const dd = ddSnap.data();
        depotInfo = `Depot Days ${dd.year||year}: ${dd.overview||""} Car show date: ${dd.carShowDate||"TBA"}. Vendors: ${(dd.vendors||[]).join(", ")||"TBA"}`;
      }
    } catch(e) { /* silent */ }
    let siteInfo = "";
    try {
      const cfgSnap = await db.doc("site_config/main").get();
      if (cfgSnap.exists) { const c=cfgSnap.data(); siteInfo=`District address: ${c.address||"Covington, TN"}. Phone: ${c.phone||"N/A"}.`; }
    } catch(e) { /* silent */ }
    const systemPrompt = `You are the friendly assistant for the Art Depot District in Covington, Tennessee.\nYou help visitors learn about the district, its businesses, events, and the annual Depot Days festival including the car show and vendor signup.\nKeep answers friendly, helpful, and concise. If you don't know something, say so and suggest they contact the district directly.\nStay on topic — only answer questions about the Art Depot District.\n\nDISTRICT INFO:\n${siteInfo}\n\nBUSINESSES:\n${businesses.join("\n")}\n\nDEPOT DAYS:\n${depotInfo}\n\nFAQs:\n${faqs.join("\n\n")}\n\nNOTES:\n- The district is also known as the Artesian Business District (city designation)\n- Depot Days is the annual festival — car show and vendor signup are part of it\n- Free parking is available throughout the district`;
    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type":"application/json","x-api-key":ANTHROPIC_API_KEY.value(),"anthropic-version":"2023-06-01" },
        body: JSON.stringify({ model:"claude-haiku-4-5-20251001", max_tokens:512, system:systemPrompt, messages:messages.slice(-10) }),
      });
      const data  = await response.json();
      const reply = data.content?.[0]?.text || "I'm not sure about that. Try contacting the district directly.";
      try { await db.collection("chat_logs").add({ question:messages[messages.length-1]?.content||"", answer:reply, timestamp:FieldValue.serverTimestamp(), sessionId:req.headers["x-session-id"]||"unknown" }); } catch(e) { /* silent */ }
      return res.json({ reply });
    } catch(e) {
      console.error("Anthropic API error:", e);
      return res.status(500).json({ reply:"Sorry, I'm having trouble right now. Please try again in a moment." });
    }
  }
);
